using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ARC.Archivos;namespace GraphApi.Services.ARC.Archivos{    public class ArchivosService : IArchivosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ArchivosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadArchivos>> GetArchivos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM arc.vsArchivos (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadArchivos>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetArchivosDynamic(            int? archivoID,            string? nombre,            string? ruta,            int? tipoArchivoID,            string? tipoArchivo,            bool? esPrivado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ArchivoID, Nombre, Ruta, TipoArchivoID, TipoArchivo, EsPrivado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM arc.vsArchivos (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (archivoID.HasValue)            {                vSql.Append(" AND ArchivoID = @ArchivoID");                vParameters.Add("ArchivoID",archivoID);            }            if (!string.IsNullOrWhiteSpace(nombre))            {                vSql.Append(" AND Nombre LIKE @Nombre");                vParameters.Add("Nombre",$"%{nombre}%");            }            if (!string.IsNullOrWhiteSpace(ruta))            {                vSql.Append(" AND Ruta LIKE @Ruta");                vParameters.Add("Ruta",$"%{ruta}%");            }            if (!string.IsNullOrWhiteSpace(tipoArchivo))            {                vSql.Append(" AND TipoArchivo LIKE @TipoArchivo");                vParameters.Add("TipoArchivo",$"%{tipoArchivo}%");            }            if (esPrivado.HasValue)            {                vSql.Append(" AND EsPrivado = @EsPrivado");                vParameters.Add("EsPrivado", esPrivado.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadArchivos> CreateArchivos(clCreateArchivos objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO arc.Archivos                (Nombre, Ruta, TipoArchivoID, EsPrivado, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Nombre, @Ruta, @TipoArchivoID, @EsPrivado, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Nombre,                objInput.Ruta,                objInput.TipoArchivoID,                objInput.EsPrivado,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ArchivoID, Nombre, Ruta, TipoArchivoID, TipoArchivo, EsPrivado, bEliminado                FROM arc.vsArchivos (NOLOCK)                WHERE ArchivoID = @ArchivoID;";            var vReadParams = new { ArchivoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadArchivos>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Archivo con ID {vNewId}.");            return vCreated;        }        public async Task<clReadArchivos?> UpdateArchivos(clUpdateArchivos objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ArchivoID", objInput.ArchivoID);            if (objInput.Nombre is not null)            {                vSets.Add("Nombre = @Nombre");                vParameters.Add("Nombre", objInput.Nombre);            }            if (objInput.Ruta is not null)            {                vSets.Add("Ruta = @Ruta");                vParameters.Add("Ruta", objInput.Ruta);            }            if (objInput.TipoArchivoID != null)            {                vSets.Add("TipoArchivoID = @TipoArchivoID");                vParameters.Add("TipoArchivoID", objInput.TipoArchivoID);            }            if (objInput.EsPrivado != null)            {                vSets.Add("EsPrivado = @EsPrivado");                vParameters.Add("EsPrivado", objInput.EsPrivado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE arc.Archivos                SET {vSetClause}                WHERE ArchivoID = @ArchivoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ArchivoID, Nombre, Ruta, TipoArchivoID, TipoArchivo, EsPrivado, bEliminado                FROM arc.vsArchivos (NOLOCK)                WHERE ArchivoID = @ArchivoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadArchivos>(sSelect, new {  objInput.ArchivoID });        }        public async Task<bool> DeleteArchivos(int nArchivosID)        {            const string sSql = @"                DELETE FROM arc.Archivos                WHERE ArchivoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nArchivosID });            return vAffected > 0;        }    }}